def solution(target_versions: set[str]) -> list[str]:
    if not target_versions:
        return ['py3', 'py2_function_print', 'py2']
    if all(version.startswith('py3') for version in target_versions):
        return ['py3', 'py2_function_print']
    # BUG: 함수형 print를 처리하는 문법 후보가 빠져 있습니다.
