import re


def solution(path: str, data: str) -> dict | None:
    # BUG: 최신 Kali가 사용하는 /etc/os-release를 확인하지 않습니다.
    if path == '/etc/lsb-release' and 'Kali' in data:
        match = re.search(r'DISTRIB_RELEASE=(.*)', data)
        return {
            'distribution': 'Kali',
            'version': match.group(1).strip() if match else None,
        }
    return None

if __name__ == '__main__':
    import json
    path = json.loads(input())
    data = json.loads(input())
    print(solution(path, data))
